(4216, 5, 1, 2, 1, 4, 769, '5.1.02.01.04.0769', 'Belanja Aset Tetap Lainnya-Barang Koleksi Non Budaya-Barang Koleksi Non Budaya-Tanaman Koleksi', NULL, NULL, '4', 0, NULL, 'Digunakan untuk mencatat belanja aset tetap lainnya-barang koleksi non budaya-barang koleksi non budaya-tanaman koleksi yang tidak memenuhi kriteria kapitalisasi sesuai dengan ketentuan peraturan perundang- undangan.', '2024-04-06 16:16:09', 'nabiila', '2024-04-06 16:16:09', 'nabiila', 0),
(4217, 5, 1, 2, 1, 4, 770, '5.1.02.01.04.0770', 'Belanja Aset Tetap Lainnya-Barang Koleksi Non Budaya-Barang Koleksi Non Budaya-Mikroba Koleksi', NULL, NULL, '4', 0, NULL, 'Digunakan untuk mencatat belanja aset tetap lainnya-barang koleksi non budaya-barang koleksi non budaya-mikroba koleksi yang tidak memenuhi kriteria kapitalisasi sesuai dengan ketentuan peraturan perundang- undangan.', '2024-04-06 16:16:09', 'nabiila', '2024-04-06 16:16:09', 'nabiila', 0),
(4218, 5, 1, 2, 1, 4, 771, '5.1.02.01.04.0771', 'Belanja Aset Tetap Lainnya-Barang Koleksi Non Budaya-Barang Koleksi Non Budaya-Batuan Koleksi', NULL, NULL, '4', 0, NULL, 'Digunakan untuk mencatat belanja aset tetap lainnya-barang koleksi non budaya-barang koleksi non budaya-batuan koleksi yang tidak memenuhi kriteria kapitalisasi sesuai dengan ketentuan peraturan perundang- undangan.', '2024-04-06 16:16:09', 'nabiila', '2024-04-06 16:16:09', 'nabiila', 0),
(4219, 5, 1, 2, 1, 4, 772, '5.1.02.01.04.0772', 'Belanja Aset Tetap Lainnya-Barang Koleksi Non Budaya-Barang Koleksi Non Budaya-Fosil', NULL, NULL, '4', 0, NULL, 'Digunakan untuk mencatat belanja aset tetap lainnya-barang koleksi non budaya-barang koleksi non budaya-fosil yang tidak memenuhi kriteria kapitalisasi sesuai dengan ketentuan peraturan perundang-undangan.', '2024-04-06 16:16:09', 'nabiila', '2024-04-06 16:16:09', 'nabiila', 0),
(4220, 5, 1, 2, 1, 4, 773, '5.1.02.01.04.0773', 'Belanja Aset Tetap Lainnya-Barang Koleksi Non Budaya-Barang Koleksi Non Budaya-Barang Koleksi Non Budaya Lainnya', NULL, NULL, '4', 0, NULL, 'Digunakan untuk mencatat belanja aset tetap lainnya-barang koleksi non budaya-barang koleksi non budaya-barang koleksi non budaya lainnya yang tidak memenuhi kriteria kapitalisasi sesuai dengan ketentuan peraturan perundang-undangan.', '2024-04-06 16:16:09', 'nabiila', '2024-04-06 16:16:09', 'nabiila', 0),
(4221, 5, 1, 2, 2, 2, 10, '5.1.02.02.02.0010', 'Belanja Iuran Jaminan Hari Tua bagi Non ASN', NULL, NULL, '4', 0, NULL, 'Digunakan untuk mencatat belanja iuran jaminan hari tua bagi tenaga non ASN yang dipekerjakan melalui perjanjian kerja/kontrak sebagai perlindungan berupa manfaat uang tunai yang dibayarkan sekaligus pada saat peserta memasuki usia pensiun, meninggal dunia, atau mengalami cacat total tetap sesuai dengan ketentuan peraturan perundang-undangan.', '2024-04-06 16:16:09', 'nabiila', '2024-04-06 16:16:09', 'nabiila', 0),
(4222, 5, 1, 2, 2, 2, 11, '5.1.02.02.02.0011', 'Belanja Iuran Jaminan Pensiun bagi Non ASN', NULL, NULL, '4', 0, NULL, 'Digunakan untuk mencatat belanja iuran jaminan pensiun bagi tenaga non ASN yang dipekerjakan melalui perjanjian kerja/kontrak sebagai perlindungan untuk mempertahankan derajat kehidupan yang layak bagi peserta dan/atau ahli warisnya dengan memberikan penghasilan setelah peserta memasuki usia pensiun, mengalami cacat total tetap, atau meninggal dunia sesuai dengan ketentuan peraturan perundang-undangan.', '2024-04-06 16:16:09', 'nabiila', '2024-04-06 16:16:09', 'nabiila', 0),
(4223, 5, 1, 2, 2, 2, 12, '5.1.02.02.02.0012', 'Belanja Iuran Jaminan Kecelakaan Kerja bagi Pekerja Rentan', NULL, NULL, '4', 0, NULL, 'Digunakan untuk mencatat belanja iuran jaminan kecelakaan kerja bagi pekerja rentan sebagai perlindungan atas risiko kecelakaan kerja atau penyakit akibat kerja berupa perawatan, santunan, dan tunjangan cacat sesuai dengan ketentuan peraturan perundang-undangan.', '2024-04-06 16:16:09', 'nabiila', '2024-04-06 16:16:09', 'nabiila', 0),
(4224, 5, 1, 2, 2, 2, 13, '5.1.02.02.02.0013', 'Belanja Iuran Jaminan Kematian bagi Pekerja Rentan', NULL, NULL, '4', 0, NULL, 'Digunakan untuk mencatat belanja iuran jaminan kematian bagi pekerja rentan sebagai perlindungan atas risiko kematian bukan akibat kecelakaan kerja berupa santunan kematian sesuai dengan ketentuan peraturan perundang-undangan.', '2024-04-06 16:16:09', 'nabiila', '2024-04-06 16:16:09', 'nabiila', 0),
(4225, 5, 1, 2, 5, 1, 8, '5.1.02.05.01.0008', 'Belanja Uang yang Diberikan kepada RT atau dengan Sebutan Lain', NULL, NULL, '4', 0, NULL, 'Digunakan untuk mencatat belanja dalam rangka melaksanakan program, kegiatan dan sub kegiatan Pemerintahan Daerah berdasarkan visi dan misi Kepala Daerah berupa uang yang diberikan kepada RT atau dengan sebutan lain sesuai dengan ketentuan peraturan perundang-undangan.', '2024-04-06 16:16:09', 'nabiila', '2024-04-06 16:16:09', 'nabiila', 0),
(4226, 5, 1, 2, 5, 1, 9, '5.1.02.05.01.0009', 'Belanja Uang yang Diberikan kepada RW atau dengan Sebutan Lain', NULL, NULL, '4', 0, NULL, 'Digunakan untuk mencatat belanja dalam rangka melaksanakan program, kegiatan dan sub kegiatan Pemerintahan Daerah berdasarkan visi dan misi Kepala Daerah berupa uang yang diberikan kepada RW atau dengan sebutan lain sesuai dengan ketentuan peraturan perundang-undangan.', '2024-04-06 16:16:09', 'nabiila', '2024-04-06 16:16:09', 'nabiila', 0),
