(37, '0000', '76.01', '1.03.0.00.0.00.01.0000', '03  TAHUN 2021', '2021-01-05', 'pengangkatan pejabat penatausahaan keuangan  dinas pekerjaan umum dan penataan ruang kabupaten pasangkayu tahun 2020', '197508022006041011', 'kepala', 'Pembina Tingkat I, IV/b', 'Budiyansa, ST', '{\"0\": {\"nip\": \"198407252009031001\", \"nama\": \"Felix Datuan, ST\", \"jabatan\": \"Kepala Sub Bagian Keuangan\", \"pangkat\": \"Penata , III/c\", \"jabatan_sk\": \"Pejabat Penatausahaan Keuangan\"}}', 0, '{\"0\": {\"isi\": \"bahwa untuk menyediakan pengelolaan keuangan Dinas Pekerjaan Umum dan Penataan Ruang Kabupaten Pasangkayu, maka dipandang perlu mengangkat Pejabat Penatausahaan Keuangan pada Dinas Pekerjaan Umum dan Penataan Ruang Kabupaten Pasangkayu;\"}, \"1\": {\"isi\": \"bahwa yang tersebut namanya dalam lampiran keputusan ini dipandang cakap dan mampu melaksanakan tugas;\"}, \"2\": {\"isi\": \"bahwa sebagaimana dimaksud pada point a perlu ditetapkan dalam keputusan Kepala Dinas Pekerjaan Umum dan Penataan Ruang.\"}}', '{\"0\": {\"isi\": \"Undang-Undang Nomor 28 Tahun 1999 tentang penyelenggaraan Negara yang bersih dan bebas dari korupsi dan nepotisme (Lembaran Negara Republik Indonesia Tahun 1999 Nomor 75, Tambahan Lembaran Negara Nomor 3851);\"}, \"1\": {\"isi\": \"Undang-Undang Nomor 7 Tahun 2003 tentang Pembentukan Kabupaten Luwu Timur dan Kabupaten Mamuju Utara di Provinsi Sulawesi Selatan (Lembaran Negara Republik Indonesia Tahun 2003 Nomor 27, Tambahan Lembaran Negara Nomor 4270);\"}, \"2\": {\"isi\": \"Undang-Undang Nomor 17 Tahun 2003 tentang Keuangan Negara (Lembaran Negara Republik Indonesia Tahun 2003 Nomor 47, Tambahan Lembaran Negara Nomor 4286);\"}, \"3\": {\"isi\": \"Undang-Undang Nomor 1 Tahun 2004 tentang Perbendaharaan Negara (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 5, Tambahan Lembaran Negara Nomor 4355);\"}, \"4\": {\"isi\": \"Undang-Undang Nomor 32 Tahun 2004 tentang Pemerintah Daerah (Lembaran Negara Republik Indonesia Tahun 2004 Nomor125, Tambahan Lembaran Negara Nomor 4437) sebagimana telah diubah beberapa kali terakhir dengan Undang-undang Nomor 12 Tahun 2008 tentang Perubahan kedua atas undang-undang Nomor 32 Tahun 2004 tentang Pemerintahan Daerah (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 59, Tambahan Lembaran Negara Nomor 4844);\"}, \"5\": {\"isi\": \"Peraturan Pemerintah Nomor 58 Tahun 2005 tentang Pengelolaan Keuangan Daerah (Lembaran Negara Republik Indonesia Tahun 2005 Nomor 140, Tambahan Lembaran Negara Republik Indonesia Nomor 4578);\"}, \"6\": {\"isi\": \"Undang-Undang Nomor 33 Tahun 2004 tentang Perimbangan Keuangan Antara Pemerintah Pusat dan Pemerintah Daerah (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 126, Tambahan Lembaran Negara Republik Indonesia Nomor 4438)\"}, \"7\": {\"isi\": \"Peraturan Pemerintah Nomor 8 Tahun 2006 tentang Laporan Keuangan dan Kinerja Instansi Pemerintah (Lembaran Negara Republik Indonesia Tahun 2006 Nomor 25, Tambahan Lembaran Negara Republik Indonesia Nomor 4614);\"}, \"8\": {\"isi\": \"Peraturan Menteri Dalam Negeri Nomor 13 Tahun 2006 tentang Pedoman Pengelolaan Keuangan Daerah sebagaimana telah diubah dengan Peraturan Menteri Dalam Negeri Nomor 59 Tahun 2007 tentang Perubahan Atas Peraturan Menteri Dalam Negeri Nomor 13 Tahun 2006 tentang Pedoman Pengelolaan Keuangan Daerah;\"}, \"9\": {\"isi\": \"Peraturan Daerah Kabupaten Pasangkayu Nomor 35 Tahun 2016 tentang Pembentukan Organisasi Perangkat Daerah;\"}, \"10\": {\"isi\": \"Peraturan Daerah Kabupaten Pasangkayu Nomor 9 Tahun 2020 tanggal 29 Desember 2020 tentang Anggaran pendapatan dan Belanja Daerah Tahun Anggaran 2021;\"}, \"11\": {\"isi\": \"Peraturan Bupati Kabupaten Pasangkayu Nomor 28 Tahun 2020 tanggal 29 Desember 2020 tentang Penjabaran Anggaran Pendapatan dan Belanja Daerah Kebupaten Pasangkayu Tahun Anggaran 2021.\"}}', '{\"0\": {\"isi\": \"Meneliti Kelengkapan SPP-LS pengadaan barang dan jasa yang disampaikan oleh bendahara pengeluaran dan diketahui/disetujui oleh PPTK;\", \"p_l\": \"P\"}, \"1\": {\"isi\": \"Meneliti kelengkapan SPP-UP, SPP-GU dan SPP-LS gaji dan tunjangan PNS serta penghasilan lainnya yang ditetapkan sesuai dengan ketentuan perundang-undangan yang diajukan oleh bendahara pengeluaran;\", \"p_l\": \"L\"}, \"2\": {\"isi\": \"Melakukan Verifikasi SPP;\", \"p_l\": \"L\"}, \"3\": {\"isi\": \"Menyiapkan SPM;\", \"p_l\": \"L\"}, \"4\": {\"isi\": \"Melakukan verifikasi harian atas penerimaan;\", \"p_l\": \"L\"}, \"5\": {\"isi\": \"Melaksanakan akuntansi SKPD; dan\", \"p_l\": \"L\"}, \"6\": {\"isi\": \"Menyiapkan laporan keuangan SKPD.\", \"p_l\": \"L\"}}', '{\"0\": {\"isi\": \"Segala biaya yang timbul akibat keputusan ini dibebankan kepada APBD Dinas Pekerjaan Umum dan Penataan Ruang Kabupaten Pasangkayu Tahun Anggaran 2021.\", \"p_l\": \"P\"}}', '{\"0\": {\"isi\": \"Keputusan ini mulai berlaku pada tanggal ditetapkan dan apabila terdapat kekeliruan didalamnya akan diperbaharui sebagaimana mestinya.\", \"p_l\": \"P\"}}', '{}', '{\"0\": {\"tembusan\": \"Bupati                                            Pasangkayu, di Pasangkayu;\"}, \"1\": {\"tembusan\": \"Sekretaris Daerah Kabupaten Pasangkayu di Pasangkayu;\"}, \"2\": {\"tembusan\": \"Inspektur Inspektorat Kabupaten Pasangkayu di Pasangkayu;\"}, \"3\": {\"tembusan\": \"Kepala Badan PKAD Kabupaten Pasangkayu di Pasangkayu;\"}, \"4\": {\"tembusan\": \"Masing-masing yang bersangkutan;\"}, \"5\": {\"tembusan\": \"Pertinggal.\"}}', '', '', '0000-00-00 00:00:00', '', '0000-00-00 00:00:00', '', 0, 0),
(38, '0000', '76.01', '1.03.0.00.0.00.01.0000', '12 TAHUN 2021', '2021-01-05', 'pengangkatan administrasi kontrak dan data dinas pekerjaan umum dan penataan ruang kabupaten pasangkayu tahun 2021', '197508022006041011', 'kepala', 'Pembina Tingkat I, IV/b', 'Budiyansa, ST', '{\"0\": {\"nip\": \"Non ASN\", \"nama\": \"Ni Made Wiryanti, S.Pd\", \"jabatan\": \"honorer\", \"pangkat\": \"-\", \"jabatan_sk\": \"administrasi kontrak dan data\"}, \"1\": {\"nip\": \"Non ASN\", \"nama\": \"Sri Suhartina, S.Ap\", \"jabatan\": \"honorer\", \"pangkat\": \"-\", \"jabatan_sk\": \"administrasi kontrak dan data\"}}', 0, '{\"0\": {\"isi\": \"bahwa untuk kelancaran pelaksanaan administrasi kontrak dan data perkantoran yang baik pada Dinas Pekerjaan Umum dan Penataan Ruang Pemerintah Daerah Kabupaten Pasangkayu, maka dipandang perlu mengangkat Pengantar Surat pada Dinas Pekerjaan Umum Kabupaten Pasangkayu;\"}, \"1\": {\"isi\": \"bahwa yang tersebut namanya dalam lampiran keputusan ini dipandang cakap dan mampu melaksanakan tugas;\"}, \"2\": {\"isi\": \"bahwa pengangkatan sebagaimana dimaksud pada point a perlu ditetapkan dalam Keputusan Kepala Dinas.\"}}', '{\"0\": {\"isi\": \"Undang-Undang Nomor 28 Tahun 1999 tentang Penyelenggaraan Pemerintahan yang bersih dan bebas Korupsi, Kolusi dan Nepotisme (Lembaran Negara Republik Indonesia Tahun 1999 Nomor 75, Tambahan Lembaran Negara Republik Indonesia Nomor 3581);\"}, \"1\": {\"isi\": \"Undang-Undang Nomor 28 tahun 2000 tentang usaha dan peran masyarakat Jasa Konstruksi (Lembaran Negara Republik Indonesia tahun 2000 Nomor 63);\"}, \"2\": {\"isi\": \"Undang-Undang Nomor 7 Tahun 2003 tentang Pembentukan Kabupaten Luwu Timur dan Kabupaten Mamuju Utara di Provinsi Sulawesi Selatan (Lembaran Negara Tahun 2003 Nomor 27, Tambahan Lembaran NegaraNomor 4270);\"}, \"3\": {\"isi\": \"Undang-Undang Nomor 17 Tahun 2003 tentang Keuangan Negara (Lembaran Negara Republik Indonesia Tahun 2003 Nomor 47, Tambahan Lembaran Negara Republik Indonesia Nomor 4286);\"}, \"4\": {\"isi\": \"Undang-Undang Nomor 1 Tahun 2004 tentang Perbendaharaan Negara (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 5, Tambahan Lembaran Negara Republik Indonesia Nomor 4355);\"}, \"5\": {\"isi\": \"Undang-Undang Nomor 33 Tahun 2004 tentang Perimbangan Keuangan Antara Pemerintah Pusat dan Pemerintah Daerah (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 126, Tambahan Lembaran Negara Republik Indonesia Nomor 4438);\"}, \"6\": {\"isi\": \"Undang-Undang Nomor 2 Tahun 2017 tentang Jasa Konstruksi;\"}, \"7\": {\"isi\": \"Peraturan Presiden Republik Indonesia Nomor 16 Tahun 2019 tentang Pengadaan Barang/Jasa Pemerintah;\"}, \"8\": {\"isi\": \"Peraturan Pemerintah Nomor 61 Tahun 2017 tentang Perubahan Nama Kabupaten Mamuju Utara menjadi Kabupaten Pasangkayu di Provinsi Sulawesi Barat (Lembaran Negara Republik Indonesia Tahun 2017 Nomor 312, Tambahan Lembaran Negara Republik Indonesia Nomor 6715);\"}, \"9\": {\"isi\": \"Peraturan Menteri Dalam Negeri Nomor 13 Tahun 2006 tentang Pedoman Pengelolaan Keuangan Daerah sebagaimana telah diubah dengan Peraturan Menteri Dalam Negeri Nomor 59 Tahun 2007 tentang Perubahan Atas Peraturan Menteri Dalam Negeri Nomor 13 Tahun 2006 tentang Pedoman Pengelolaan Keuangan Daerah;\"}, \"10\": {\"isi\": \"Peraturan Menteri Dalam Negeri Nomor 64 Tahun 2020 tentang Pedoman Penyusunan Anggaran Pendapatan dan Belanja Daerah Tahun Anggaran 2021\"}, \"11\": {\"isi\": \"Peraturan Daerah Kabupaten Mamuju Utara Nomor 5 Tahun 2006 tentang pokok-pokok Pengelolaan Keuangan Daerah (Lembaran Daerah Nomor 5 Tahun 2006, Tambahan Lembaran Daerah Nomor 5);\"}, \"12\": {\"isi\": \"Peraturan Daerah Kabupaten Pasangkayu Nomor 9 Tahun 2020 tanggal 29 Desember 2020 tentang Anggaran pendapatan dan Belanja Daerah Tahun Anggaran 2021;\"}, \"13\": {\"isi\": \"Peraturan Bupati Kabupaten Pasangkayu Nomor 28 Tahun 2020 tanggal 29 Desember 2020 tentang Penjabaran Anggaran Pendapatan dan Belanja Daerah Kebupaten Pasangkayu Tahun Anggaran 2021.\"}}', '{\"0\": {\"isi\": \"Tugas Personil sebagaimana dimaksud pada diktum Penetapan adalah sebagai berikut :\", \"p_l\": \"P\"}, \"1\": {\"isi\": \"Mencatat, memeriksa dan memastikan kontraktual dan swakelola OPD;\", \"p_l\": \"L\"}, \"2\": {\"isi\": \"Melakukan Entri Data Kontrak dan realisasi anggaran OPD;\", \"p_l\": \"L\"}, \"3\": {\"isi\": \"Melaporkan hasil pelaksanaan tugas secara tertulis dan lisan kepada atasan sesuai prosedur yang berlaku;\", \"p_l\": \"L\"}, \"4\": {\"isi\": \"Melaksanakan tugas kedinasan lain yang diperintahkan pimpinan baik tertulis maupun lisan.\", \"p_l\": \"L\"}}', '{\"0\": {\"isi\": \"Segala biaya yang timbul akibat keputusan ini dibebankan kepada Pos Anggaran Dinas Pekerjaan Umum dan Penataan Ruang Kabupaten Pasangkayu Tahun Anggaran 2021.\", \"p_l\": \"P\"}}', '{\"0\": {\"isi\": \"Keputusan ini mulai berlaku pada tanggal ditetapkan dan apabila terdapat kekeliruan didalamnya akan diperbaharui sebagaimana mestinya.\", \"p_l\": \"P\"}}', '{}', '{\"0\": {\"tembusan\": \"Bupati                                            Pasangkayu, di Pasangkayu\"}, \"1\": {\"tembusan\": \"Sekretaris Daerah Kabupaten Pasangkayu di Pasangkayu\"}, \"2\": {\"tembusan\": \"Inspektur Inspektorat Kabupaten Pasangkayu di Pasangkayu\"}, \"3\": {\"tembusan\": \"Kepala Badan PKAD Kabupaten Pasangkayu di Pasangkayu\"}, \"4\": {\"tembusan\": \"Masing-masing yang bersangkutan\"}, \"5\": {\"tembusan\": \"Pertinggal\"}}', '', '', '0000-00-00 00:00:00', '', '0000-00-00 00:00:00', '', 0, 0),
(39, '0000', '76.01', '1.03.0.00.0.00.01.0000', '19 TAHUN 2021', '2021-03-29', 'perubahan penetapan pengangkatan pejabat pengadaan barang / jasa pemerintah pada dinas pekerjaan umum dan penataan ruang kabupaten pasangkayu tahun 2021', '197508022006041011', 'kepala', 'Pembina Tingkat I, IV/b', 'Budiyansa, ST', '{\"0\": {\"nip\": \"198404262011011011\", \"nama\": \"I Ketut Suriyana, ST\", \"jabatan\": \"Kasie Air Minum\", \"pangkat\": \"Penata , III/c\", \"jabatan_sk\": \"Pejabat Pengadaan Bidang Cipta Karya\"}, \"1\": {\"nip\": \"198007112006041010\", \"nama\": \"Alwi Mansyur, A.Md\", \"jabatan\": \"Plt. kasubag program\", \"pangkat\": \"Penata Muda, III/b\", \"jabatan_sk\": \"Pejabat Pengadaan Bidang Binamarga/Sekretariat dan Pembinaan Jasa Konstruksi\"}, \"2\": {\"nip\": \"197603042011011003\", \"nama\": \"Ariyadi\", \"jabatan\": \"STAFF\", \"pangkat\": \"Pengatur , II/c\", \"jabatan_sk\": \"Pejabat Pengadaan Bidang Sumber Daya Air\"}}', 0, '{\"0\": {\"isi\": \"bahwa untuk pelaksanaan proses kerja pengelolaan Barang / Jasa yang efektif, efisien dan akuntabel pada Dinas Pekerjaan Umum dan Penataan Ruang Pemerintah Daerah Kabupaten Pasangkayu, maka dipandang perlu mengangkat Pejabat Pengadaan Barang / Jasa pada Dinas Pekerjaan Umum dan Penataan Ruang Kabupaten Pasangkayu\"}, \"1\": {\"isi\": \"bahwa yang tersebut namanya dalam lampiran keputusan ini dipandang cakap dan mampu melaksanakan tugas\"}, \"2\": {\"isi\": \"bahwa pengangkatan sebagaimana dimaksud pada point a perlu ditetapkan dalam Keputusan Kepala Dinas\"}}', '{\"0\": {\"isi\": \"Undang-Undang Nomor 28 Tahun 1999 tentang Penyelenggaraan Pemerintahan yang bersih dan bebas Korupsi, Kolusi dan Nepotisme (Lembaran Negara Republik Indonesia Tahun 1999 Nomor 75, Tambahan Lembaran Negara Republik Indonesia Nomor 3581)\"}, \"1\": {\"isi\": \"Undang-Undang Nomor 28 tahun 2000 tentang usaha dan peran masyarakat Jasa Konstruksi (Lembaran Negara Republik Indonesia tahun 2000 Nomor 63)\"}, \"2\": {\"isi\": \"Undang-Undang Nomor 7 Tahun 2003 tentang Pembentukan Kabupaten Luwu Timur dan Kabupaten Mamuju Utara di Provinsi Sulawesi Selatan (Lembaran Negara Tahun 2003 Nomor 27, Tambahan Lembaran Negara Nomor 4270)\"}, \"3\": {\"isi\": \"Undang-Undang Nomor 17 Tahun 2003 tentang Keuangan Negara (Lembaran Negara Republik Indonesia Tahun 2003 Nomor 47, Tambahan Lembaran Negara Republik Indonesia Nomor 4286)\"}, \"4\": {\"isi\": \"Undang-Undang Nomor 1 Tahun 2004 tentang Perbendaharaan Negara (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 5, Tambahan Lembaran Negara Republik Indonesia Nomor 4355)\"}, \"5\": {\"isi\": \"Undang-Undang Nomor 32 Tahun 2004 tentang Pemerintahan Daerah (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 125, Tambahan Lembaran Negara Republik Indonesia Nomor 4437) sebagaimana telah diubah dengan Undang-Undang Nomor 8 Tahun 2005 tentang Penetapan Peraturan Pemerintah Pengganti Undang-Undang Nomor 3 Tahun 2005 tentang Perubahan Undang-Undang Nomor 32 Tahun 2004 tentang Pemerintahan Daerah menjadi Undang-Undang (Lembaran Negara Republik Indonesia Tahun 2005 Nomor 108, Tambahan Lembaran Negara Republik Indonesia Nomor 4548)\"}, \"6\": {\"isi\": \"Undang-Undang Nomor 33 Tahun 2004 tentang Perimbangan Keuangan Antara Pemerintah Pusat dan Pemerintah Daerah (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 126, Tambahan Lembaran Negara Republik Indonesia Nomor 4438)\"}, \"7\": {\"isi\": \"Undang-Undang Nomor 2 Tahun 2017 tentang Jasa Konstruksi\"}, \"8\": {\"isi\": \"Peraturan Presiden Republik Indonesia Nomor 16 Tahun 2018 tentang Pengadaan Barang/Jasa Pemerintah\"}, \"9\": {\"isi\": \"Peraturan Menteri Dalam Negeri Nomor 13 Tahun 2006 tentang Pedoman Pengelolaan Keuangan Daerah sebagaimana telah diubah dengan Peraturan Menteri Dalam Negeri Nomor 59 Tahun 2007 tentang Perubahan Atas Peraturan Menteri Dalam Negeri Nomor 13 Tahun 2006 tentang Pedoman Pengelolaan Keuangan Daerah\"}, \"10\": {\"isi\": \"Peraturan Menteri Dalam Negeri Nomor 64 Tahun 2020 tentang Pedoman Penyusunan Anggaran Pendapatan dan Belanja Daerah Tahun Anggaran 2021\"}, \"11\": {\"isi\": \"Peraturan Daerah Kabupaten Mamuju Utara Nomor 5 Tahun 2006 tentang pokok-pokok Pengelolaan Keuangan Daerah (Lembaran Daerah Nomor 5 Tahun 2006, Tambahan Lembaran Daerah Nomor 5)\"}, \"12\": {\"isi\": \"Peraturan Daerah Kabupaten Pasangkayu Nomor 35 Tahun 2016 tentang Pembentukan Organisasi Perangkat Daerah\"}, \"13\": {\"isi\": \"Peraturan Daerah Kabupaten Pasangkayu Nomor 9 Tahun 2020 tanggal 29 Desember 2020 tentang Anggaran pendapatan dan Belanja Daerah Tahun Anggaran 2021;\"}, \"14\": {\"isi\": \"Peraturan Bupati Kabupaten Pasangkayu Nomor 28 Tahun 2020 tanggal 29 Desember 2020 tentang Penjabaran Anggaran Pendapatan dan Belanja Daerah Kebupaten Pasangkayu Tahun Anggaran 2021.\"}}', '{\"0\": {\"isi\": \"Tugas Pejabat sebagaimana dimaksud pada diktum Kesatu adalah :\", \"p_l\": \"P\"}, \"1\": {\"isi\": \"melaksanakan persiapan dan pelaksanaan Pengadaan Langsung;\", \"p_l\": \"L\"}, \"2\": {\"isi\": \"melaksanakan persiapan dan pelaksanaan Penunjukan Langsung untuk pengadaan Barang/Pekerjaan Konstruksi/Jasa Lainnya yang bernilai paling banyak Rp200.000.000,00 (dua ratus juta rupiah);\", \"p_l\": \"L\"}, \"3\": {\"isi\": \"melaksanakan persiapan dan pelaksanaan Penunjukan Langsung untuk pengadaan Jasa Konsultansi yang bernilai paling banyak Rp100.000.000,00 (seratus juta rupiah);\", \"p_l\": \"L\"}, \"4\": {\"isi\": \"melaksanakan E-purchasing yang bernilai paling banyak Rp200.000.000,00 (dua ratus juta rupiah);\", \"p_l\": \"L\"}, \"5\": {\"isi\": \"Menyerahkan dokumen asli pemilihan penyedia barang / jasa Pemerintah kepada pengguna anggaran;\", \"p_l\": \"L\"}, \"6\": {\"isi\": \"Membuat laporan mengenai proses dan hasil pengadaan kepada pengguna anggaran; dan\", \"p_l\": \"L\"}, \"7\": {\"isi\": \"Memberikan pertanggungjawaban atas pelaksanaan kegiatan pengadaan barang / jasa Konstruksi kepada pengguna anggaran\", \"p_l\": \"L\"}}', '{\"0\": {\"isi\": \"Mencabut surat keputusan Nomor 06 TAHUN 2021 tertanggal 5 Januari 2021 tentang pengangkatan Pejabat/Panitia Pemeriksa Hasil Pekerjaan pada dinas pekerjaan umum dan penataan ruang kabupaten pasangkayu tahun 2021;\", \"p_l\": \"L\"}, \"1\": {\"isi\": \"Segala biaya yang timbul akibat keputusan ini dibebankan kepada Pos Anggaran Dinas Pekerjaan Umum dan Penataan Ruang Kabupaten Pasangkayu Tahun Anggaran 2021\", \"p_l\": \"L\"}}', '{\"0\": {\"isi\": \"Keputusan ini mulai berlaku pada tanggal ditetapkan dan apabila terdapat kekeliruan didalamnya akan diperbaharui sebagaimana mestinya\", \"p_l\": \"P\"}}', '{}', '{\"0\": {\"tembusan\": \"Bupati                                            Pasangkayu, di Pasangkayu\"}, \"1\": {\"tembusan\": \"Sekretaris Daerah Kabupaten Pasangkayu di Pasangkayu\"}, \"2\": {\"tembusan\": \"Inspektur Inspektorat Kabupaten Pasangkayu di Pasangkayu\"}, \"3\": {\"tembusan\": \"Kepala Badan PKAD Kabupaten Pasangkayu di Pasangkayu\"}, \"4\": {\"tembusan\": \"Masing-masing yang bersangkutan\"}, \"5\": {\"tembusan\": \"Pertinggal\"}}', '', '', '0000-00-00 00:00:00', '', '0000-00-00 00:00:00', '', 0, 0),
(40, '0000', '76.01', '1.03.0.00.0.00.01.0000', '13 TAHUN 2021', '2021-01-05', 'pengangkatan tenaga non pns jasa kebersihan kantor dinas pekerjaan umum dan penataan ruang kabupaten pasangkayu tahun 2021', '197508022006041011', 'kepala', 'Pembina Tingkat I, IV/b', 'Budiyansa, ST', '{\"0\": {\"nip\": \"Non ASN\", \"nama\": \"Muh. Fikrih Anugrah\", \"jabatan\": \"honorer\", \"pangkat\": \"Juru , I/-\", \"jabatan_sk\": \"tenaga non pns jasa kebersihan kantor\"}, \"1\": {\"nip\": \"Non ASN\", \"nama\": \"Kasriadi\", \"jabatan\": \"honorer\", \"pangkat\": \"Juru , I/-\", \"jabatan_sk\": \"tenaga non pns jasa kebersihan kantor\"}, \"2\": {\"nip\": \"Non ASN\", \"nama\": \"Musdalipa\", \"jabatan\": \"honorer\", \"pangkat\": \"Juru , I/-\", \"jabatan_sk\": \"tenaga non pns jasa kebersihan kantor\"}, \"3\": {\"nip\": \"Non ASN\", \"nama\": \"Herlin\", \"jabatan\": \"honorer\", \"pangkat\": \"Juru , I/-\", \"jabatan_sk\": \"tenaga non pns jasa kebersihan kantor\"}}', 0, '{\"0\": {\"isi\": \"bahwa untuk kebersihan dan kenyamanan pada kantor Dinas Pekerjaan Umum dan Penataan Ruang Pemerintah Daerah Kabupaten Pasangkayu, maka dipandang perlu mengangkat tenaga non pns jasa kebersihan kantor pada Dinas Pekerjaan Umum Kabupaten Pasangkayu;\"}, \"1\": {\"isi\": \"bahwa yang tersebut namanya dalam lampiran keputusan ini dipandang cakap dan mampu melaksanakan tugas;\"}, \"2\": {\"isi\": \"bahwa pengangkatan sebagaimana dimaksud pada point a perlu ditetapkan dalam Keputusan Kepala Dinas.\"}}', '{\"0\": {\"isi\": \"Undang-Undang Nomor 28 Tahun 1999 tentang Penyelenggaraan Pemerintahan yang bersih dan bebas Korupsi, Kolusi dan Nepotisme (Lembaran Negara Republik Indonesia Tahun 1999 Nomor 75, Tambahan Lembaran Negara Republik Indonesia Nomor 3581);\"}, \"1\": {\"isi\": \"Undang-Undang Nomor 28 tahun 2000 tentang usaha dan peran masyarakat Jasa Konstruksi (Lembaran Negara Republik Indonesia tahun 2000 Nomor 63);\"}, \"2\": {\"isi\": \"Undang-Undang Nomor 7 Tahun 2003 tentang Pembentukan Kabupaten Luwu Timur dan Kabupaten Mamuju Utara di Provinsi Sulawesi Selatan (Lembaran Negara Tahun 2003 Nomor 27, Tambahan Lembaran NegaraNomor 4270);\"}, \"3\": {\"isi\": \"Undang-Undang Nomor 17 Tahun 2003 tentang Keuangan Negara (Lembaran Negara Republik Indonesia Tahun 2003 Nomor 47, Tambahan Lembaran Negara Republik Indonesia Nomor 4286);\"}, \"4\": {\"isi\": \"Undang-Undang Nomor 1 Tahun 2004 tentang Perbendaharaan Negara (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 5, Tambahan Lembaran Negara Republik Indonesia Nomor 4355);\"}, \"5\": {\"isi\": \"Undang-Undang Nomor 33 Tahun 2004 tentang Perimbangan Keuangan Antara Pemerintah Pusat dan Pemerintah Daerah (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 126, Tambahan Lembaran Negara Republik Indonesia Nomor 4438);\"}, \"6\": {\"isi\": \"Undang-Undang Nomor 2 Tahun 2017 tentang Jasa Konstruksi;\"}, \"7\": {\"isi\": \"Peraturan Presiden Republik Indonesia Nomor 16 Tahun 2019 tentang Pengadaan Barang/Jasa Pemerintah;\"}, \"8\": {\"isi\": \"Peraturan Pemerintah Nomor 61 Tahun 2017 tentang Perubahan Nama Kabupaten Mamuju Utara menjadi Kabupaten Pasangkayu di Provinsi Sulawesi Barat (Lembaran Negara Republik Indonesia Tahun 2017 Nomor 312, Tambahan Lembaran Negara Republik Indonesia Nomor 6715);\"}, \"9\": {\"isi\": \"Peraturan Menteri Dalam Negeri Nomor 13 Tahun 2006 tentang Pedoman Pengelolaan Keuangan Daerah sebagaimana telah diubah dengan Peraturan Menteri Dalam Negeri Nomor 59 Tahun 2007 tentang Perubahan Atas Peraturan Menteri Dalam Negeri Nomor 13 Tahun 2006 tentang Pedoman Pengelolaan Keuangan Daerah;\"}, \"10\": {\"isi\": \"Peraturan Menteri Dalam Negeri Nomor 64 Tahun 2020 tentang Pedoman Penyusunan Anggaran Pendapatan dan Belanja Daerah Tahun Anggaran 2021\"}, \"11\": {\"isi\": \"Peraturan Daerah Kabupaten Mamuju Utara Nomor 5 Tahun 2006 tentang pokok-pokok Pengelolaan Keuangan Daerah (Lembaran Daerah Nomor 5 Tahun 2006, Tambahan Lembaran Daerah Nomor 5);\"}, \"12\": {\"isi\": \"Peraturan Daerah Kabupaten Pasangkayu Nomor 9 Tahun 2020 tanggal 29 Desember 2020 tentang Anggaran pendapatan dan Belanja Daerah Tahun Anggaran 2021;\"}, \"13\": {\"isi\": \"Peraturan Bupati Kabupaten Pasangkayu Nomor 28 Tahun 2020 tanggal 29 Desember 2020 tentang Penjabaran Anggaran Pendapatan dan Belanja Daerah Kebupaten Pasangkayu Tahun Anggaran 2021.\"}}', '{\"0\": {\"isi\": \"Tugas Personil sebagaimana dimaksud pada diktum Kesatu adalah sebagai berikut :\", \"p_l\": \"P\"}, \"1\": {\"isi\": \"menjaga kebersihan isi dan halaman kantor;\", \"p_l\": \"L\"}, \"2\": {\"isi\": \"Membersihkan isi dan halaman kantor;\", \"p_l\": \"L\"}, \"3\": {\"isi\": \"Melaksanakan tugas kedinasan lain yang diperintahkan pimpinan dan staff baik tertulis maupun lisan.\", \"p_l\": \"L\"}}', '{\"0\": {\"isi\": \"Segala biaya yang timbul akibat keputusan ini dibebankan kepada Pos Anggaran Dinas Pekerjaan Umum dan Penataan Ruang Kabupaten Pasangkayu Tahun Anggaran 2021.\", \"p_l\": \"P\"}}', '{\"0\": {\"isi\": \"Keputusan ini mulai berlaku pada tanggal ditetapkan dan apabila terdapat kekeliruan didalamnya akan diperbaharui sebagaimana mestinya.\", \"p_l\": \"P\"}}', '{}', '{\"0\": {\"tembusan\": \"Bupati                                            Pasangkayu, di Pasangkayu\"}, \"1\": {\"tembusan\": \"Sekretaris Daerah Kabupaten Pasangkayu di Pasangkayu\"}, \"2\": {\"tembusan\": \"Inspektur Inspektorat Kabupaten Pasangkayu di Pasangkayu\"}, \"3\": {\"tembusan\": \"Kepala Badan PKAD Kabupaten Pasangkayu di Pasangkayu\"}, \"4\": {\"tembusan\": \"Masing-masing yang bersangkutan\"}, \"5\": {\"tembusan\": \"Pertinggal\"}}', '', '', '0000-00-00 00:00:00', '', '0000-00-00 00:00:00', '', 0, 0),
