(59, '0000', '76.01', '1.03.0.00.0.00.01.0000', '04 TAHUN 2022', '2022-01-03', 'pengangkatan pejabat pelaksana teknis kegiatan (PPTK) dan tim teknis dinas pekerjaan umum dan penataan ruang kabupaten pasangkayu tahun 2022', '197508022006041011', 'kepala', 'Pembina Tingkat I, IV/b', 'Budiyansa, ST', '{\"0\":{\"nama\":\"Nurmadina, S.Sos.M.Si\",\"pangkat\":\"Penata Tingkat I , III/d\",\"nip\":\"198208022003122003\",\"jabatan\":\"Pembina jasa konstruksi\",\"jabatan_sk\":\"PPTK/Tim Pembinaan Jasa Konstruksi\"},\"1\":{\"nama\":\"Muh. Hirman Madjid, ST\",\"pangkat\":\"Penata , III/c\",\"nip\":\"197511282011011002\",\"jabatan\":\"Tehnik tata bangunan dan perumahan\",\"jabatan_sk\":\"PPTK/Tim Teknis Bangunan Gedung dan Lingkungan\"},\"2\":{\"nama\":\"Rahmania, ST\",\"pangkat\":\"Penata , III/c\",\"nip\":\"198406172009032002\",\"jabatan\":\"Tehnik penyehatan lingkungan\",\"jabatan_sk\":\"PPTK/Tim Teknis Sanitasi dan Penyehatan Lingkungan\"},\"3\":{\"nama\":\"I Ketut Suriyana, ST\",\"pangkat\":\"Penata , III/c\",\"nip\":\"198404262011011011\",\"jabatan\":\"Tehnik penyehatan lingkungan\",\"jabatan_sk\":\"PPTK/Tim Teknis Air Minum\"},\"4\":{\"nama\":\"Patahuddin, ST. M.AP\",\"pangkat\":\"Penata Tingkat I, III/d\",\"nip\":\"197110122009031001\",\"jabatan\":\"Tehnik jalan dan jembatan\",\"jabatan_sk\":\"PPTK/Tim Teknis Pembangunan Jalan, Pemeliharaan Jalan dan Peralatan\"},\"5\":{\"nama\":\"Suriyana, ST\",\"pangkat\":\"Penata Muda Tingkat I, III/b\",\"nip\":\"198001282012122003\",\"jabatan\":\"Tehnik tata bangunan dan perumahan\",\"jabatan_sk\":\"PPTK/Tim Teknis Bidang Penataan Ruang\"},\"6\":{\"nama\":\"Evi Yanti, ST\",\"pangkat\":\"Penata Tingkat I, III/d\",\"nip\":\"197701272008042001\",\"jabatan\":\"Fungsional\",\"jabatan_sk\":\"PPTK/Tim Teknis Pembangunan Jembatan, Pemeliharaan Jembatan, Penggantian Jembatan\"},\"7\":{\"nama\":\"Irmawati, SE\",\"pangkat\":\"Penata , III/c\",\"nip\":\"197601032006042007\",\"jabatan\":\"kasubag umum dan kepegawaian\",\"jabatan_sk\":\"PPTK Sekretariat\"}}', 0, '{\"0\":{\"isi\":\"bahwa untuk pelaksanaan proses kerja Pengadaan Barang / Jasa Pemerintah yang efektif, efisien dan akuntabel pada Dinas Pekerjaan Umum dan Penataan Ruang Pemerintah Daerah Kabupaten Pasangkayu, maka dipandang perlu mengangkat Pejabat Pelaksana Teknis Kegiatan (PPTK) dan tim teknis pada Dinas Pekerjaan Umum Kabupaten Pasangkayu Tahun 2021;\"},\"1\":{\"isi\":\"bahwa yang tersebut namanya dalam lampiran keputusan ini dipandang cakap dan mampu melaksanakan tugas;\"},\"2\":{\"isi\":\"bahwa pengangkatan sebagaimana dimaksud pada point a perlu ditetapkan dalam Keputusan Kepala Dinas.\"}}', '{\"0\":{\"isi\":\"Undang-Undang Nomor 28 Tahun 1999 tentang Penyelenggaraan Pemerintahan yang bersih dan bebas Korupsi, Kolusi dan Nepotisme (Lembaran Negara Republik Indonesia Tahun 1999 Nomor 75, Tambahan Lembaran Negara Republik Indonesia Nomor 3581);\"},\"1\":{\"isi\":\"Undang-Undang Nomor 28 tahun 2000 tentang usaha dan peran masyarakat Jasa Konstruksi (Lembaran Negara Republik Indonesia tahun 2000 Nomor 63);\"},\"2\":{\"isi\":\"Undang-Undang Nomor 7 Tahun 2003 tentang Pembentukan Kabupaten Luwu Timur dan Kabupaten Mamuju Utara di Provinsi Sulawesi Selatan (Lembaran Negara Tahun 2003 Nomor 27, Tambahan Lembaran NegaraNomor 4270);\"},\"3\":{\"isi\":\"Undang-Undang Nomor 17 Tahun 2003 tentang Keuangan Negara (Lembaran Negara Republik Indonesia Tahun 2003 Nomor 47, Tambahan Lembaran Negara Republik Indonesia Nomor 4286);\"},\"4\":{\"isi\":\"Undang-Undang Nomor 1 Tahun 2004 tentang Perbendaharaan Negara (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 5, Tambahan Lembaran Negara Republik Indonesia Nomor 4355);\"},\"5\":{\"isi\":\"Undang-Undang Nomor 33 Tahun 2004 tentang Perimbangan Keuangan Antara Pemerintah Pusat dan Pemerintah Daerah (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 126, Tambahan Lembaran Negara Republik Indonesia Nomor 4438);\"},\"6\":{\"isi\":\"Undang-Undang Nomor 2 Tahun 2017 tentang Jasa Konstruksi;\"},\"7\":{\"isi\":\"Peraturan Presiden Republik Indonesia Nomor 16 Tahun 2019 tentang Pengadaan Barang/Jasa Pemerintah;\"},\"8\":{\"isi\":\"Peraturan Pemerintah Nomor 61 Tahun 2017 tentang Perubahan Nama Kabupaten Mamuju Utara menjadi Kabupaten Pasangkayu di Provinsi Sulawesi Barat (Lembaran Negara Republik Indonesia Tahun 2017 Nomor 312, Tambahan Lembaran Negara Republik Indonesia Nomor 6715);\"},\"9\":{\"isi\":\"Peraturan Menteri Dalam Negeri Nomor 13 Tahun 2006 tentang Pedoman Pengelolaan Keuangan Daerah sebagaimana telah diubah dengan Peraturan Menteri Dalam Negeri Nomor 59 Tahun 2007 tentang Perubahan Atas Peraturan Menteri Dalam Negeri Nomor 13 Tahun 2006 tentang Pedoman Pengelolaan Keuangan Daerah;\"},\"10\":{\"isi\":\"Peraturan Menteri Dalam Negeri Nomor 27 Tahun 2021 tentang Pedoman Penyusunan Anggaran Pendapatan dan Belanja Daerah Tahun Anggaran 2022;\"},\"11\":{\"isi\":\"Peraturan Daerah Kabupaten Mamuju Utara Nomor 5 Tahun 2006 tentang pokok-pokok Pengelolaan Keuangan Daerah (Lembaran Daerah Nomor 5 Tahun 2006, Tambahan Lembaran Daerah Nomor 5);\"},\"12\":{\"isi\":\"Peraturan Daerah Kabupaten Pasangkayu Nomor 7 Tahun 2021 tanggal 30 Desember 2021 tentang Anggaran pendapatan dan Belanja Daerah Tahun Anggaran 2022;\"},\"13\":{\"isi\":\"Peraturan Bupati Kabupaten Pasangkayu Nomor 34 Tahun 2021 tanggal 31 Desember 2021 tentang Penjabaran Anggaran Pendapatan dan Belanja Daerah Kebupaten Pasangkayu Tahun Anggaran 2022.\"}}', '{\"0\":{\"isi\":\"Tugas Pejabat sebagaimana dimaksud pada diktum Kesatu adalah :\",\"p_l\":\"P\"},\"1\":{\"isi\":\"Mengendalikan pelaksanaan kegiatan;\",\"p_l\":\"L\"},\"2\":{\"isi\":\"Melaporkan perkembangan pelaksanaan kegiatan;\",\"p_l\":\"L\"},\"3\":{\"isi\":\"Menyiapkan dokumen anggaran atas beban pengeluaran pelaksanaan kegiatan;dan\",\"p_l\":\"L\"},\"4\":{\"isi\":\"Membantu Pejabat Pembuat Komitmen dalam melaksanakan tugasnya.\",\"p_l\":\"L\"}}', '{\"0\":{\"isi\":\"Segala biaya yang timbul akibat keputusan ini dibebankan kepada Pos Anggaran Dinas Pekerjaan Umum dan Penataan Ruang Kabupaten Pasangkayu Tahun Anggaran 2022.\",\"p_l\":\"P\"}}', '{\"0\":{\"isi\":\"Keputusan ini mulai berlaku pada tanggal ditetapkan dan apabila terdapat kekeliruan didalamnya akan diperbaharui sebagaimana mestinya.\",\"p_l\":\"P\"}}', '{}', '{\"0\":{\"tembusan\":\"Bupati                                            Pasangkayu, di Pasangkayu\"},\"1\":{\"tembusan\":\"Sekretaris Daerah Kabupaten Pasangkayu di Pasangkayu\"},\"2\":{\"tembusan\":\"Inspektur Inspektorat Kabupaten Pasangkayu di Pasangkayu\"},\"3\":{\"tembusan\":\"Kepala Badan PKAD Kabupaten Pasangkayu di Pasangkayu\"},\"4\":{\"tembusan\":\"Masing-masing yang bersangkutan\"},\"5\":{\"tembusan\":\"Pertinggal\"}}', '', '', '0000-00-00 00:00:00', '', '0000-00-00 00:00:00', '', 0, 0),
(60, '0000', '76.01', '1.03.0.00.0.00.01.0000', '20 TAHUN 2022', '2022-01-03', 'pembentukan tim koordinasi, survey dan pelaporan dana Lokasi khusus 2022', '197508022006041011', 'kepala', 'Pembina Tingkat I, IV/b', 'Budiyansa, ST', '{\"0\":{\"nama\":\"Budiyansa, ST\",\"pangkat\":\"Pembina Tingkat I, IV/b\",\"nip\":\"197508022006041011\",\"jabatan\":\"kepala dinas\",\"jabatan_sk\":\"Pembina\"},\"1\":{\"nama\":\"Sumarlin, ST\",\"pangkat\":\"Pembina , IV/a\",\"nip\":\"198006152006041018\",\"jabatan\":\"sekretaris dinas\",\"jabatan_sk\":\"Sekretaris\"},\"2\":{\"nama\":\"I Nyoman Sumerta, ST\",\"pangkat\":\"Penata , III/c\",\"nip\":\"198301012010011020\",\"jabatan\":\"Kabid Binamarga\",\"jabatan_sk\":\"Ketua\"},\"3\":{\"nama\":\"Abd. Rasyid, S.pd,M.pd\",\"pangkat\":\"Pembina , IV/a\",\"nip\":\"196704051991031015\",\"jabatan\":\"kabid cipta karya\",\"jabatan_sk\":\"Koordinator\"},\"4\":{\"nama\":\"Herry Hasanuddin. M, ST\",\"pangkat\":\"Penata Tingkat I, III/d\",\"nip\":\"197101152007011019\",\"jabatan\":\"kabid penataan ruang\",\"jabatan_sk\":\"Koordinator\"},\"5\":{\"nama\":\"Pusmahasib, S.Si\",\"pangkat\":\"Penata , III/c\",\"nip\":\"197908252009031003\",\"jabatan\":\"kabid sumber daya air\",\"jabatan_sk\":\"Koordinator\"},\"6\":{\"nama\":\"Felix Datuan, ST\",\"pangkat\":\"Penata , III/c\",\"nip\":\"198407252009031001\",\"jabatan\":\"kasubag keuangan\",\"jabatan_sk\":\"Anggota\"},\"7\":{\"nama\":\"Irmawati, SE\",\"pangkat\":\"Penata , III/c\",\"nip\":\"197601032006042007\",\"jabatan\":\"kasubag umum dan kepegawaian\",\"jabatan_sk\":\"Anggota\"}}', 0, '{\"0\":{\"isi\":\"bahwa untuk Peningkatan akuntabilitas dan pelaporan DAK pada sektor infrastruktur khususnya Bidang Binamarga serta Peningkatan kemampuan Pemda untuk menghasilkan output dan laporan DAK yang dipersyaratkan dan meningkatkan pengendalian internal Pemerintah Daerah Kabupaten Pasangkayu, maka dipandang perlu mengangkat Tim Koordinasi dan Petugas Pelaporan Monitoring Dana Alokasi Khusus Bidang Infrastruktur tahun anggaran 2022;\"},\"1\":{\"isi\":\"bahwa yang tersebut namanya dalam lampiran keputusan ini dipandang cakap dan mampu melaksanakan tugas;\"},\"2\":{\"isi\":\"bahwa pengangkatan sebagaimana dimaksud pada point a perlu ditetapkan dalam Keputusan Kepala Dinas.\"}}', '{\"0\":{\"isi\":\"Undang-Undang Nomor 28 Tahun 1999 tentang Penyelenggaraan Pemerintahan yang bersih dan bebas Korupsi, Kolusi dan Nepotisme (Lembaran Negara Republik Indonesia Tahun 1999 Nomor 75, Tambahan Lembaran Negara Republik Indonesia Nomor 3581);\"},\"1\":{\"isi\":\"Undang-Undang Nomor 28 tahun 2000 tentang usaha dan peran masyarakat Jasa Konstruksi (Lembaran Negara Republik Indonesia tahun 2000 Nomor 63);\"},\"2\":{\"isi\":\"Undang-Undang Nomor 7 Tahun 2003 tentang Pembentukan Kabupaten Luwu Timur dan Kabupaten Mamuju Utara di Provinsi Sulawesi Selatan (Lembaran Negara Tahun 2003 Nomor 27, Tambahan Lembaran NegaraNomor 4270);\"},\"3\":{\"isi\":\"Undang-Undang Nomor 17 Tahun 2003 tentang Keuangan Negara (Lembaran Negara Republik Indonesia Tahun 2003 Nomor 47, Tambahan Lembaran Negara Republik Indonesia Nomor 4286);\"},\"4\":{\"isi\":\"Undang-Undang Nomor 1 Tahun 2004 tentang Perbendaharaan Negara (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 5, Tambahan Lembaran Negara Republik Indonesia Nomor 4355);\"},\"5\":{\"isi\":\"Undang-Undang Nomor 33 Tahun 2004 tentang Perimbangan Keuangan Antara Pemerintah Pusat dan Pemerintah Daerah (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 126, Tambahan Lembaran Negara Republik Indonesia Nomor 4438);\"},\"6\":{\"isi\":\"Undang-Undang Nomor 2 Tahun 2017 tentang Jasa Konstruksi;\"},\"7\":{\"isi\":\"Peraturan Presiden Republik Indonesia Nomor 16 Tahun 2019 tentang Pengadaan Barang/Jasa Pemerintah;\"},\"8\":{\"isi\":\"Peraturan Pemerintah Nomor 61 Tahun 2017 tentang Perubahan Nama Kabupaten Mamuju Utara menjadi Kabupaten Pasangkayu di Provinsi Sulawesi Barat (Lembaran Negara Republik Indonesia Tahun 2017 Nomor 312, Tambahan Lembaran Negara Republik Indonesia Nomor 6715);\"},\"9\":{\"isi\":\"Peraturan Menteri Dalam Negeri Nomor 13 Tahun 2006 tentang Pedoman Pengelolaan Keuangan Daerah sebagaimana telah diubah dengan Peraturan Menteri Dalam Negeri Nomor 59 Tahun 2007 tentang Perubahan Atas Peraturan Menteri Dalam Negeri Nomor 13 Tahun 2006 tentang Pedoman Pengelolaan Keuangan Daerah;\"},\"10\":{\"isi\":\"Peraturan Menteri Dalam Negeri Nomor 64 Tahun 2020 tentang Pedoman Penyusunan Anggaran Pendapatan dan Belanja Daerah Tahun Anggaran 2021\"},\"11\":{\"isi\":\"Peraturan Daerah Kabupaten Mamuju Utara Nomor 5 Tahun 2006 tentang pokok-pokok Pengelolaan Keuangan Daerah (Lembaran Daerah Nomor 5 Tahun 2006, Tambahan Lembaran Daerah Nomor 5);\"},\"12\":{\"isi\":\"Peraturan Daerah Kabupaten Pasangkayu Nomor 9 Tahun 2020 tanggal 29 Desember 2020 tentang Anggaran pendapatan dan Belanja Daerah Tahun Anggaran 2021;\"},\"13\":{\"isi\":\"Peraturan Bupati Kabupaten Pasangkayu Nomor 28 Tahun 2020 tanggal 29 Desember 2020 tentang Penjabaran Anggaran Pendapatan dan Belanja Daerah Kebupaten Pasangkayu Tahun Anggaran 2021.\"}}', '{\"0\":{\"isi\":\"Tugas Pejabat sebagaimana dimaksud pada diktum Kesatu adalah :\",\"p_l\":\"P\"},\"1\":{\"isi\":\"Melakukan Review dan Verifikasi usulan proposal DAK Bidang Infrastruktur Kabupaten, selanjutnya usulan proposal DAK kabupaten;\",\"p_l\":\"L\"},\"2\":{\"isi\":\"Melakukan verifikasi Data teknis Dak bidang infrastruktur secara berkala;\",\"p_l\":\"L\"},\"3\":{\"isi\":\"Membantu pelaksanaan sosialisasi,Diseminasi,Dan pembinaan pelaksanaan Kepada daerah yang mendapat dan bidang infrastruktur;\",\"p_l\":\"L\"},\"4\":{\"isi\":\"Melaksanakan pemantauannya terhadap pelaksanaan dak bidang infrastruktur oleh pemerintah Kabupaten;\",\"p_l\":\"L\"},\"5\":{\"isi\":\"Kegiatan pemantauan termasuk diantaranya Inventarisasi permasalahan terkait pencapaian progres fisik dan keuangan dak bidang infrastruktur di daerah;\",\"p_l\":\"L\"},\"6\":{\"isi\":\"Melaksanakan evaluasi terhadap pelaksanaan dak bidang infrastruktur Oleh pemerintah Kabupaten\",\"p_l\":\"L\"},\"7\":{\"isi\":\"Memberikan saran, Masukan, maupun rekomendasi kepada Bupati terkait penyelenggaraan dan ke depan di Kabupaten;\",\"p_l\":\"L\"},\"8\":{\"isi\":\"Menyiapkan laporan triwulanan dan tahunan terkait penyelenggaraan dak bidang infrastruktur di Kabupaten,Terkait Dan menyampaikan Kepada Tim koordinasi kementerian DAKÃÂ ÃÂ bidang Infrastruktur Sebagaimana mekanisme pelaporan dalam peraturan menteri Pekerjaan umum dan perumahan rakyat.\",\"p_l\":\"L\"}}', '{\"0\":{\"isi\":\"Segala biaya yang timbul akibat keputusan ini dibebankan kepada Pos Anggaran Dinas Pekerjaan Umum dan Penataan Ruang Kabupaten Pasangkayu Tahun Anggaran 2022.\",\"p_l\":\"P\"}}', '{\"0\":{\"isi\":\"Keputusan ini mulai berlaku pada tanggal ditetapkan dan apabila terdapat kekeliruan didalamnya akan diperbaharui sebagaimana mestinya.\",\"p_l\":\"P\"}}', '{}', '{\"0\":{\"tembusan\":\"Bupati                                            Pasangkayu, di Pasangkayu\"},\"1\":{\"tembusan\":\"Sekretaris Daerah Kabupaten Pasangkayu di Pasangkayu\"},\"2\":{\"tembusan\":\"Inspektur Inspektorat Kabupaten Pasangkayu di Pasangkayu\"},\"3\":{\"tembusan\":\"Kepala Badan PKAD Kabupaten Pasangkayu di Pasangkayu\"},\"4\":{\"tembusan\":\"Masing-masing yang bersangkutan\"},\"5\":{\"tembusan\":\"Pertinggal\"}}', '', '', '0000-00-00 00:00:00', '', '0000-00-00 00:00:00', '', 0, 0),
