INSERT INTO `sumber_dana_neo` (`id`, `sumber_dana`, `kelompok`, `jenis_akun`, `objek`, `rincian_objek`, `sub_rincian_objek`, `kode`, `uraian`, `peraturan`, `disable`, `aksi`, `keterangan`, `username_insert`, `tgl_insert`, `tgl_update`, `username_update`, `is_deleted`) VALUES
(1, 1, 1, 0, 0, 0, 0, '1.1', 'PENDAPATAN ASLI DAERAH (PAD)', '4', 0, NULL, '', 'nabiila', '2024-04-06 16:14:01', '2024-04-06 16:14:01', 'nabiila', 0),
(2, 1, 1, 0, 0, 0, 0, '1.1.1', 'Pajak Daerah', '4', 0, NULL, '', 'nabiila', '2024-04-06 16:14:01', '2024-04-06 16:14:01', 'nabiila', 0),
(3, 1, 1, 0, 1, 0, 0, '1.1.1.01', 'Pajak Kendaraan Bermotor (PKB)', '4', 0, NULL, 'Digunakan untuk mencatat belanja/pengeluaran pembiayaan yang bersumber dari PKB mobil penumpang-sedan, PKB-mobil penumpang-jeep, PKB-mobil penumpang-minibus, PKB-mobil bus-microbus, PKB-mobil bus-bus, PKB-mobil barang/beban-pick up, PKB- mobil barang/beban-light truck, PKB-mobil barang/beban-truck, PKB-mobil barang/beban-blind van, PKB-sepeda motor-sepeda motor roda dua, PKB-sepeda motor- sepeda motor roda tiga, PKB-kendaraan bermotor yang dioperasikan di air, PKB- kendaraan khusus alat berat/alat besar, dan PKB-mobil roda tiga.', 'nabiila', '2024-04-06 16:14:01', '2024-04-06 16:14:01', 'nabiila', 0),
(4, 1, 1, 0, 2, 0, 0, '1.1.1.02', 'Bea Balik Nama Kendaraan Bermotor (BBNKB)', '4', 0, NULL, 'Digunakan untuk mencatat belanja/pengeluaran pembiayaan yang bersumber dari BBNKB-mobil penumpang-sedan, BBNKB-mobil penumpang-jeep, BBNKB-mobil penumpang-minibus, BBNKB-mobil bus-microbus, BBNKB-mobil bus-bus, BBNKB- mobil barang/beban-pick up, BBNKB-mobil barang/beban-light truck, BBNKB-mobil barang/beban-truck, BBNKB-mobil barang/beban-blind van, BBNKB-sepeda motor- sepeda motor roda dua, BBNKB-sepeda motor-sepeda motor roda tiga, BBNKB- kendaraan bermotor yang dioperasikan di air, BBNKB-kendaraan khusus alat berat, dan BBNKB-mobil roda tiga.', 'nabiila', '2024-04-06 16:14:01', '2024-04-06 16:14:01', 'nabiila', 0),
(5, 1, 1, 0, 3, 0, 0, '1.1.1.03', 'Pajak Bahan Bakar Kendaraan Bermotor (PBBKB)', '4', 0, NULL, 'Digunakan untuk mencatat belanja/pengeluaran pembiayaan yang bersumber dari PBBKB-bahan bakar bensin, PBBKB-bahan bakar solar, PBBKB-bahan bakar gas, dan PBBKB-bahan bakar lainnya.', 'nabiila', '2024-04-06 16:14:01', '2024-04-06 16:14:01', 'nabiila', 0),
(6, 1, 1, 0, 4, 0, 0, '1.1.1.04', 'Pajak Air Permukaan', '4', 0, NULL, 'Digunakan untuk mencatat belanja/pengeluaran pembiayaan yang bersumber dari pajak air permukaan.', 'nabiila', '2024-04-06 16:14:01', '2024-04-06 16:14:01', 'nabiila', 0),
(7, 1, 1, 0, 5, 0, 0, '1.1.1.05', 'Pajak Rokok', '4', 0, NULL, 'Digunakan untuk mencatat belanja/pengeluaran pembiayaan yang bersumber dari pajak rokok.', 'nabiila', '2024-04-06 16:14:01', '2024-04-06 16:14:01', 'nabiila', 0),
(8, 1, 1, 0, 6, 0, 0, '1.1.1.06', 'Pajak Hotel', '4', 0, NULL, 'Digunakan untuk mencatat belanja/pengeluaran pembiayaan yang bersumber dari pajak hotel, pajak motel, pajak losmen, pajak gubuk pariwisata, pajak wisma pariwisata, pajak pesanggrahan, pajak rumah penginapan dan sejenisnya, serta pajak rumah kos dengan jumlah kamar lebih dari 10 (sepuluh).', 'nabiila', '2024-04-06 16:14:01', '2024-04-06 16:14:01', 'nabiila', 0),
(9, 1, 1, 0, 7, 0, 0, '1.1.1.07', 'Pajak Restoran', '4', 0, NULL, 'Digunakan untuk mencatat belanja/pengeluaran pembiayaan yang bersumber dari pajak restoran dan sejenisnya, pajak rumah makan dan sejenisnya, pajak kafetaria dan sejenisnya, pajak kantin dan sejenisnya, pajak warung dan sejenisnya, pajak bar dan sejenisnya, serta pajak jasa boga/katering dan sejenisnya.', 'nabiila', '2024-04-06 16:14:01', '2024-04-06 16:14:01', 'nabiila', 0),
(10, 1, 1, 0, 8, 0, 0, '1.1.1.08', 'Pajak Hiburan', '4', 0, NULL, 'Digunakan untuk mencatat belanja/pengeluaran pembiayaan yang bersumber dari pajak tontonan film, pajak pagelaran kesenian/musik/ tari/busana, pajak kontes kecantikan, binaraga, dan sejenisnya, pajak pameran, pajak diskotik, karaoke, klub malam dan sejenisnya, pajak sirkus/akrobat/sulap, pajak permainan biliar dan bowling, pajak pacuan kuda, kendaraan bermotor, dan permainan ketangkasan, pajak panti pijat, refleksi, mandi uap/spa dan pusat kebugaran (fitness center), serta pajak pertandingan olahraga.', 'nabiila', '2024-04-06 16:14:01', '2024-04-06 16:14:01', 'nabiila', 0),
(11, 1, 1, 0, 9, 0, 0, '1.1.1.09', 'Pajak Reklame', '4', 0, NULL, 'Digunakan untuk mencatat belanja/pengeluaran pembiayaan yang bersumber dari pajak reklame papan/billboard/videotron/megatron, pajak reklame kain, pajak reklame melekat/stiker, pajak reklame selebaran, pajak reklame berjalan, pajak reklame udara, pajak reklame apung, pajak reklame suara, pajak reklame film/slide, dan pajak reklame peragaan.', 'nabiila', '2024-04-06 16:14:01', '2024-04-06 16:14:01', 'nabiila', 0),
(12, 1, 1, 0, 10, 0, 0, '1.1.1.10', 'Pajak Penerangan Jalan', '4', 0, NULL, 'Digunakan untuk mencatat belanja/pengeluaran pembiayaan yang bersumber dari pajak penerangan jalan.', 'nabiila', '2024-04-06 16:14:01', '2024-04-06 16:14:01', 'nabiila', 0),
(13, 1, 1, 0, 11, 0, 0, '1.1.1.11', 'Pajak Parkir', '4', 0, NULL, 'Digunakan untuk mencatat belanja/pengeluaran pembiayaan yang bersumber dari pajak parkir.', 'nabiila', '2024-04-06 16:14:01', '2024-04-06 16:14:01', 'nabiila', 0),
(14, 1, 1, 0, 12, 0, 0, '1.1.1.12', 'Pajak Air Tanah', '4', 0, NULL, 'Digunakan untuk mencatat belanja/pengeluaran pembiayaan yang bersumber dari pajak air tanah.', 'nabiila', '2024-04-06 16:14:01', '2024-04-06 16:14:01', 'nabiila', 0),
(15, 1, 1, 0, 13, 0, 0, '1.1.1.13', 'Pajak Sarang Burung Walet', '4', 0, NULL, 'Digunakan untuk mencatat belanja/pengeluaran pembiayaan yang bersumber dari pajak sarang burung walet.', 'nabiila', '2024-04-06 16:14:01', '2024-04-06 16:14:01', 'nabiila', 0),
(16, 1, 1, 0, 14, 0, 0, '1.1.1.14', 'Pajak Mineral Bukan Logam dan Batuan', '4', 0, NULL, 'Digunakan untuk mencatat belanja/pengeluaran pembiayaan yang bersumber dari pajak asbes, pajak batu tulis, pajak batu setengah permata, pajak batu kapur, pajak batu apung, pajak batu permata, pajak bentonit, pajak dolomit, pajak felspar, pajak garam batu (halite), pajak grafit, pajak granit/andesit, pajak gips, pajak kalsit, pajak kaolin, pajak leusit, pajak magnesit, pajak mika, pajak marmer, pajak nitrat, pajak opsidien, pajak oker, pajak pasir dan kerikil, pajak pasir kuarsa, pajak perlit, pajak phospat, pajak talk, pajak tanah serap (fullers earth), pajak tanah diatome, pajak tanah liat, pajak tawas (alum), pajak tras, pajak yarosif, pajak zeolit, pajak basal, pajak trakit, dan pajak mineral bukan logam dan batuan lainnya.', 'nabiila', '2024-04-06 16:14:01', '2024-04-06 16:14:01', 'nabiila', 0),
(17, 1, 1, 0, 15, 0, 0, '1.1.1.15', 'Pajak Bumi dan Bangunan Pedesaan dan Perkotaan', '4', 0, NULL, 'Digunakan untuk mencatat belanja/pengeluaran pembiayaan yang bersumber dari pajak bumi dan bangunan perdesaan dan perkotaan.', 'nabiila', '2024-04-06 16:14:01', '2024-04-06 16:14:01', 'nabiila', 0),
(18, 1, 1, 0, 16, 0, 0, '1.1.1.16', 'Bea Perolehan Hak Atas Tanah dan Bangunan (BPHTB)', '4', 0, NULL, 'Digunakan untuk mencatat belanja/pengeluaran pembiayaan yang bersumber dari BPHTB-pemindahan hak dan BPHTB-pemberian hak baru.', 'nabiila', '2024-04-06 16:14:01', '2024-04-06 16:14:01', 'nabiila', 0),
(19, 1, 1, 0, 0, 0, 0, '1.1.2', 'Retribusi Daerah - LRA', '4', 0, NULL, '', 'nabiila', '2024-04-06 16:14:01', '2024-04-06 16:14:01', 'nabiila', 0),
(20, 1, 1, 0, 1, 0, 0, '1.1.2.01', 'Retribusi Jasa Umum', '4', 0, NULL, 'Digunakan untuk mencatat belanja/pengeluaran pembiayaan yang bersumber dari retribusi pelayanan kesehatan, retribusi pelayanan persampahan/kebersihan, retribusi pelayanan pemakaman dan pengabuan mayat, retribusi pelayanan parkir di tepi jalan umum, retribusi pelayanan pasar, retribusi pengujian kendaraan bermotor, retribusi pemeriksaan alat pemadam kebakaran, retribusi penggantian biaya cetak peta, retribusi penyediaan dan/atau penyedotan kakus, retribusi pengolahan limbah cair, retribusi pelayanan tera/tera ulang, retribusi pelayanan pendidikan, serta retribusi pengawasan dan pengendalian menara telekomunikasi.', 'nabiila', '2024-04-06 16:14:01', '2024-04-06 16:14:01', 'nabiila', 0),
(21, 1, 1, 0, 2, 0, 0, '1.1.2.02', 'Retribusi Jasa Usaha', '4', 0, NULL, 'Digunakan untuk mencatat belanja/pengeluaran pembiayaan yang bersumber dari retribusi pemakaian kekayaan daerah, retribusi pasar grosir dan/atau pertokoan, retribusi penyediaan tempat pelelangan, retribusi terminal, retribusi tempat khusus parkir, retribusi tempat penginapan/pesanggrahan/ vila, retribusi rumah potong hewan, retribusi pelayanan kepelabuhan, retribusi tempat rekreasi dan olahraga, retribusi penyeberangan air, dan retribusi penjualan produksi usaha daerah.', 'nabiila', '2024-04-06 16:14:01', '2024-04-06 16:14:01', 'nabiila', 0),
(22, 1, 1, 0, 3, 0, 0, '1.1.2.03', 'Retribusi Perizinan Tertentu', '4', 0, NULL, 'Digunakan untuk mencatat belanja/pengeluaran pembiayaan yang bersumber dari retribusi izin mendirikan bangunan, retribusi izin tempat penjualan minuman beralkohol, retribusi izin trayek untuk menyediakan pelayanan angkutan umum, retribusi izin usaha perikanan, retribusi pengendalian lalu lintas, retribusi perpanjangan Izin Mempekerjakan Tenaga Kerja Asing (IMTA), retribusi persetujuan bangunan gedung, retribusi penggunaan tenaga kerja asing, dan retribusi pertambangan rakyat.', 'nabiila', '2024-04-06 16:14:01', '2024-04-06 16:14:01', 'nabiila', 0),
(23, 1, 1, 0, 0, 0, 0, '1.1.3', 'Hasil Pengelolaan Kekayaan Daerah yang Dipisahkan', '4', 0, NULL, '', 'nabiila', '2024-04-06 16:14:01', '2024-04-06 16:14:01', 'nabiila', 0),
(24, 1, 1, 0, 1, 0, 0, '1.1.3.01', 'Bagian Laba yang Dibagikan kepada Pemerintah Daerah (Dividen) atas Penyertaan Modal pada Perusahaan Milik Pemerintah/BUMN', '4', 0, NULL, 'Digunakan untuk mencatat belanja/pengeluaran pembiayaan yang bersumber dari bagian laba yang dibagikan kepada pemerintah daerah (dividen) atas penyertaan modal pada perusahaan milik pemerintah/BUMN.', 'nabiila', '2024-04-06 16:14:01', '2024-04-06 16:14:01', 'nabiila', 0),
(25, 1, 1, 0, 2, 0, 0, '1.1.3.02', 'Bagian Laba yang Dibagikan kepada Pemerintah Daerah (Dividen) atas Penyertaan Modal pada Perusahaan Milik Daerah/BUMD', '4', 0, NULL, 'Digunakan untuk mencatat belanja/pengeluaran pembiayaan yang bersumber dari bagian laba yang dibagikan kepada pemerintah daerah (dividen) atas penyertaan modal pada perusahaan milik daerah/BUMD.', 'nabiila', '2024-04-06 16:14:01', '2024-04-06 16:14:01', 'nabiila', 0),
(26, 1, 1, 0, 3, 0, 0, '1.1.3.03', 'Bagian Laba yang dibagikan kepada Pemerintah Daerah (Dividen) atas Penyertaan Modal pada Perusahaan Milik Swasta', '4', 0, NULL, 'Digunakan untuk mencatat belanja/pengeluaran pembiayaan yang bersumber dari bagian laba yang dibagikan kepada pemerintah daerah (dividen) atas penyertaan modal pada perusahaan milik swasta.', 'nabiila', '2024-04-06 16:14:01', '2024-04-06 16:14:01', 'nabiila', 0),
(27, 1, 1, 0, 0, 0, 0, '1.1.4', 'Lain-lain PAD Yang Sah', '4', 0, NULL, '', 'nabiila', '2024-04-06 16:14:01', '2024-04-06 16:14:01', 'nabiila', 0),
(28, 1, 1, 0, 1, 0, 0, '1.1.4.01', 'Hasil Penjualan BMD yang Tidak Dipisahkan', '4', 0, NULL, 'Digunakan untuk mencatat belanja/pengeluaran pembiayaan yang bersumber dari hasil penjualan tanah, hasil penjualan peralatan dan mesin, hasil penjualan gedung dan bangunan, hasil penjualan jalan, jaringan, dan irigasi, hasil penjualan aset tetap lainnya, hasil penjualan aset lainnya-tagihan jangka panjang, serta hasil penjualan aset lainnya-aset tidak berwujud.', 'nabiila', '2024-04-06 16:14:01', '2024-04-06 16:14:01', 'nabiila', 0),
(29, 1, 1, 0, 2, 0, 0, '1.1.4.02', 'Hasil Selisih Lebih Tukar Menukar BMD yang Tidak Dipisahkan', '4', 0, NULL, 'Digunakan untuk mencatat belanja/pengeluaran pembiayaan yang bersumber dari hasil selisih lebih tukar menukar tanah, hasil selisih lebih tukar menukar peralatan dan mesin, hasil selisih lebih tukar menukar gedung dan bangunan, hasil selisih lebih tukar menukar jalan, jaringan dan irigasi, hasil selisih lebih tukar menukar aset tetap lainnya, serta hasil selisih lebih tukar menukar aset lainnya-aset tak berwujud.', 'nabiila', '2024-04-06 16:14:01', '2024-04-06 16:14:01', 'nabiila', 0),
(30, 1, 1, 0, 3, 0, 0, '1.1.4.03', 'Hasil Pemanfaatan BMD yang Tidak Dipisahkan', '4', 0, NULL, 'Digunakan untuk mencatat belanja/pengeluaran pembiayaan yang bersumber dari hasil sewa BMD, hasil kerja sama pemanfaatan BMD, hasil dari bangun guna serah, hasil dari bangun serah guna, dan hasil dari kerja sama penyediaan infrastruktur.', 'nabiila', '2024-04-06 16:14:01', '2024-04-06 16:14:01', 'nabiila', 0),
(31, 1, 1, 0, 4, 0, 0, '1.1.4.04', 'Hasil Kerja Sama Daerah', '4', 0, NULL, 'Digunakan untuk mencatat belanja/pengeluaran pembiayaan yang bersumber dari hasil kerja sama daerah.', 'nabiila', '2024-04-06 16:14:01', '2024-04-06 16:14:01', 'nabiila', 0),
(32, 1, 1, 0, 5, 0, 0, '1.1.4.05', 'Jasa Giro', '4', 0, NULL, 'Digunakan untuk mencatat belanja/pengeluaran pembiayaan yang bersumber dari jasa giro pada kas daerah, jasa giro pada kas di bendahara, jasa giro pada rekening dana cadangan, jasa giro pada rekening dana BOS, dan jasa giro dana kapitasi pada FKTP.', 'nabiila', '2024-04-06 16:14:01', '2024-04-06 16:14:01', 'nabiila', 0),
(33, 1, 1, 0, 6, 0, 0, '1.1.4.06', 'Hasil Pengelolaan Dana Bergulir', '4', 0, NULL, 'Digunakan untuk mencatat belanja/pengeluaran pembiayaan yang bersumber dari hasil pengelolaan dana bergulir.', 'nabiila', '2024-04-06 16:14:01', '2024-04-06 16:14:01', 'nabiila', 0),
(34, 1, 1, 0, 7, 0, 0, '1.1.4.07', 'Pendapatan Bunga', '4', 0, NULL, 'Digunakan untuk mencatat belanja/pengeluaran pembiayaan yang bersumber dari pendapatan bunga atas penempatan uang pemerintah daerah.', 'nabiila', '2024-04-06 16:14:01', '2024-04-06 16:14:01', 'nabiila', 0),
(35, 1, 1, 0, 8, 0, 0, '1.1.4.08', 'Penerimaan atas Tuntutan Ganti Kerugian Keuangan Daerah', '4', 0, NULL, 'Digunakan untuk mencatat belanja/pengeluaran pembiayaan yang bersumber dari tuntutan ganti kerugian daerah terhadap bendahara dan tuntutan ganti kerugian daerah terhadap pegawai negeri bukan bendahara atau pejabat lain.', 'nabiila', '2024-04-06 16:14:01', '2024-04-06 16:14:01', 'nabiila', 0),
(36, 1, 1, 0, 9, 0, 0, '1.1.4.09', 'Penerimaan Komisi, Potongan, atau Bentuk Lain', '4', 0, NULL, 'Digunakan untuk mencatat belanja/pengeluaran pembiayaan yang bersumber dari penerimaan komisi, potongan, atau bentuk lain.', 'nabiila', '2024-04-06 16:14:01', '2024-04-06 16:14:01', 'nabiila', 0),
(37, 1, 1, 0, 10, 0, 0, '1.1.4.10', 'Penerimaan Keuntungan dari Selisih Nilai Tukar Rupiah terhadap Mata Uang Asing', '4', 0, NULL, 'Digunakan untuk mencatat belanja/pengeluaran pembiayaan yang bersumber dari penerimaan keuntungan dari selisih nilai tukar rupiah terhadap mata uang asing.', 'nabiila', '2024-04-06 16:14:01', '2024-04-06 16:14:01', 'nabiila', 0),
(38, 1, 1, 0, 11, 0, 0, '1.1.4.11', 'Pendapatan Denda atas Keterlambatan Pelaksanaan Pekerjaan', '4', 0, NULL, 'Digunakan untuk mencatat belanja/pengeluaran pembiayaan yang bersumber dari pendapatan denda atas keterlambatan pelaksanaan pekerjaan.', 'nabiila', '2024-04-06 16:14:01', '2024-04-06 16:14:01', 'nabiila', 0),
(39, 1, 1, 0, 12, 0, 0, '1.1.4.12', 'Pendapatan Denda Pajak Daerah', '4', 0, NULL, 'Digunakan untuk mencatat belanja/pengeluaran pembiayaan yang bersumber dari pendapatan denda pajak kendaraan bermotor, pendapatan denda bea balik nama kendaraan bermotor, pendapatan denda pajak bahan bakar kendaraan bermotor, pendapatan denda pajak air permukaan, pendapatan denda pajak rokok, pendapatan denda pajak hotel, pendapatan denda pajak restoran, pendapatan denda pajak hiburan, pendapatan denda pajak reklame, pendapatan denda pajak penerangan jalan, pendapatan denda pajak parkir, pendapatan denda pajak air tanah, pendapatan denda pajak sarang burung walet, pendapatan denda pajak mineral bukan logam dan batuan, pendapatan denda pajak bumi dan bangunan perdesaan dan perkotaan, serta pendapatan denda bea perolehan hak atas tanah dan bangunan.', 'nabiila', '2024-04-06 16:14:01', '2024-04-06 16:14:01', 'nabiila', 0),
(40, 1, 1, 0, 13, 0, 0, '1.1.4.13', 'Pendapatan Denda Retribusi Daerah', '4', 0, NULL, 'Digunakan untuk mencatat belanja/pengeluaran pembiayaan yang bersumber dari pendapatan denda retribusi jasa umum, pendapatan denda retribusi jasa usaha, dan pendapatan denda retribusi perizinan tertentu.', 'nabiila', '2024-04-06 16:14:01', '2024-04-06 16:14:01', 'nabiila', 0),
(41, 1, 1, 0, 14, 0, 0, '1.1.4.14', 'Pendapatan Hasil Eksekusi atas Jaminan', '4', 0, NULL, 'Digunakan untuk mencatat belanja/pengeluaran pembiayaan yang bersumber dari hasil eksekusi atas jaminan atas pengadaan barang/jasa.', 'nabiila', '2024-04-06 16:14:01', '2024-04-06 16:14:01', 'nabiila', 0),
(42, 1, 1, 0, 15, 0, 0, '1.1.4.15', 'Pendapatan dari Pengembalian', '4', 0, NULL, 'Digunakan untuk mencatat belanja/pengeluaran pembiayaan yang bersumber dari pendapatan dari pengembalian kelebihan pembayaran pajak penghasilan pasal 21, pendapatan dari pengembalian kelebihan pembayaran iuran simpanan peserta tabungan perumahan rakyat ASN, pendapatan dari pengembalian kelebihan pembayaran gaji dan tunjangan, pendapatan dari pengembalian kelebihan pembayaran perjalanan dinas, pendapatan dari pengembalian kelebihan pembayaran jaminan kecelakaan kerja serta pendapatan dari pengembalian kelebihan pembayaran jaminan kematian.', 'nabiila', '2024-04-06 16:14:01', '2024-04-06 16:14:01', 'nabiila', 0),
(43, 1, 1, 0, 16, 0, 0, '1.1.4.16', 'Pendapatan dari BLUD', '4', 0, NULL, 'Digunakan untuk mencatat belanja/pengeluaran pembiayaan yang bersumber dari pendapatan jasa layanan umum BLUD, pendapatan hibah BLUD, pendapatan hasil kerja sama BLUD, pendapatan dari APBD, dan pendapatan lain-lain BLUD yang sah.', 'nabiila', '2024-04-06 16:14:01', '2024-04-06 16:14:01', 'nabiila', 0),
(44, 1, 1, 0, 17, 0, 0, '1.1.4.17', 'Pendapatan Denda Pemanfaatan BMD yang tidak Dipisahkan', '4', 0, NULL, 'Digunakan untuk mencatat belanja/pengeluaran pembiayaan yang bersumber dari pendapatan denda sewa BMD, pendapatan denda hasil kerja sama pemanfaatan BMD, pendapatan denda hasil dari bangun guna serah, pendapatan denda hasil dari bangun serah guna, dan pendapatan denda hasil dari kerja sama penyediaan infrastruktur.', 'nabiila', '2024-04-06 16:14:01', '2024-04-06 16:14:01', 'nabiila', 0),
